+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "endprocessesaction.h"
+
+#include "devicenotifier_debug.h"
+
+#include <QCoreApplication>
+#include <QProcess>
+#include <QRegularExpression>
+#include <QTimer>
+
+#include <KLocalizedString>
+
+#include <Solid/OpticalDisc>
+
+#include <signal.h>
+
+EndProcessesAction::EndProcessesAction(const std::shared_ptr<StorageInfo> &storageInfo,
+                                       const std::shared_ptr<StateInfo> &stateInfo,
+                                       ActionInterface *unmountAction,
+                                       QObject *parent)
+    : ActionInterface(storageInfo, stateInfo, parent)
+    , m_unmountAction(unmountAction)
+{
+    connect(m_stateInfo.get(), &StateInfo::stateChanged, this, &EndProcessesAction::updateIsValid);
+}
+
+EndProcessesAction::~EndProcessesAction() = default;
+
+void EndProcessesAction::triggered()
+{
+    auto *access = m_storageInfo->device().as<Solid::StorageAccess>();
+    if (!access) {
+        return;
+    }
+
+    auto p = new QProcess(this);
+    connect(p, &QProcess::errorOccurred, p, &QObject::deleteLater);
+    connect(p, &QProcess::finished, this, [p, this] {
+        QList<int> pids;
+        const QString out = QString::fromLatin1(p->readAll());
+        const auto pidList = QStringView(out).split(QRegularExpression(QStringLiteral("\\s+")), Qt::SkipEmptyParts);
+        for (const QStringView pidStr : pidList) {
+            const int pid = pidStr.toInt();
+            if (!pid || pid == QCoreApplication::applicationPid()) {
+                continue;
+            }
+            if (::kill(pid, SIGTERM) == 0) {
+                qCDebug(APPLETS::DEVICENOTIFIER) << "End Processes Action: Sent SIGTERM to" << pid;
+                pids << pid;
+            }
+        }
+        p->deleteLater();
+        unmountWhenEnded(pids, 0);
+    });
+    p->start(QStringLiteral("lsof"), {QStringLiteral("-t"), access->filePath()});
+}
+
+void EndProcessesAction::unmountWhenEnded(const QList<int> &pids, int attempts)
+{
+    QList<int> running;
+    for (const int pid : pids) {
+        if (::kill(pid, 0) == 0) {
+            running << pid;
+        }
+    }
+
+    // Give the processes a few seconds to quit on their own before killing them (interactive shells ignore SIGTERM)
+    if (!running.isEmpty() && attempts == 30) {
+        for (const int pid : running) {
+            qCDebug(APPLETS::DEVICENOTIFIER) << "End Processes Action: Sending SIGKILL to" << pid;
+            ::kill(pid, SIGKILL);
+        }
+    }
+
+    if (!running.isEmpty() && attempts < 40) {
+        QTimer::singleShot(100, this, [running, attempts, this] {
+            unmountWhenEnded(running, attempts + 1);
+        });
+        return;
+    }
+
+    m_unmountAction->triggered();
+}
+
+bool EndProcessesAction::isValid() const
+{
+    return m_stateInfo->getState() == StateInfo::UnmountDone && m_stateInfo->getOperationResult() == Solid::ErrorType::DeviceBusy && m_stateInfo->isMounted();
+}
+
+QString EndProcessesAction::name() const
+{
+    return QStringLiteral("EndProcesses");
+}
+
+QString EndProcessesAction::icon() const
+{
+    return QStringLiteral("process-stop");
+}
+
+QString EndProcessesAction::text() const
+{
+    if (m_storageInfo->device().is<Solid::OpticalDisc>()) {
+        return i18nc("@action:button end the processes that keep the disc busy, then eject it", "End Blocking Processes and Eject");
+    }
+    return i18nc("@action:button end the processes that keep the device busy, then unmount it", "End Blocking Processes and Remove");
+}
+
+void EndProcessesAction::updateIsValid(const QString &udi)
+{
+    Q_UNUSED(udi);
+
+    Q_EMIT isValidChanged(name(), isValid());
+}
+
+#include "moc_endprocessesaction.cpp"
