+{
+    Q_OBJECT
+
+public:
+    explicit EndProcessesAction(const std::shared_ptr<StorageInfo> &storageInfo,
+                                const std::shared_ptr<StateInfo> &stateInfo,
+                                ActionInterface *unmountAction,
+                                QObject *parent = nullptr);
+    ~EndProcessesAction() override;
+
